     give:{when:"Once they say not everyone buys right away.",
       html:"<p>Assume <b>20%</b> (early adopters) buy in year one.</p>"},
     num:{value:330e6, tol:.05, unit:"$ in year one"},
     listen:["Says only early adopters buy at first","44,000 × $7,500 = $330M"],
